"""Template for a state-fee deferral motion."""


def generate_deferral(applicant, court, amount, reason):
    return {"status": "ok", "text": f"В {court}\n\nХОДАТАЙСТВО об отсрочке уплаты государственной пошлины\n\n{applicant} просит предоставить отсрочку уплаты государственной пошлины в размере {amount} руб. на основании статьи 333.41 НК РФ и статьи 102 АПК РФ. В связи с {reason} немедленная уплата пошлины затруднительна. Согласно пункту 4 Постановления Пленума ВАС РФ № 20 суд вправе учесть имущественное положение заявителя.\n\nПриложения:\n1. Справка ИФНС об открытых банковских счетах.\n2. Справки банков об остатках денежных средств.\n3. Справки банков об отсутствии картотеки № 2 (неисполненных расчетных документов).", "legal_basis": ["ст. 333.41 НК РФ", "ст. 102 АПК РФ", "п. 4 Постановления Пленума ВАС РФ № 20"]}
